def oracle(input):
    n = input[0]
    s = input[1]
    packs = []
    stars = []
    i = 0
    while i < n:
        c = s[i]
        if c == 'P':
            packs.append(i)
        elif c == '*':
            stars.append(i)
        i += 1
    def can(t):
        j = 0
        m = len(stars)
        pi = 0
        while pi < len(packs) and j < m:
            p = packs[pi]
            if stars[j] < p:
                if p - stars[j] > t:
                    return False
                l = stars[j]
                a = t - 2 * (p - l)
                b = (t - (p - l)) // 2
                if a > b:
                    reach = p + a
                else:
                    reach = p + b
                while j < m and stars[j] <= reach:
                    j += 1
            else:
                reach = p + t
                while j < m and stars[j] <= reach:
                    j += 1
            pi += 1
        return j == m
    lo = 0
    hi = 2 * n
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def oracle(input):
    n = input[0]
    pattern = input[1]
    m = input[2]
    words = input[3:3+m]

    revealed = {}
    guessed = {}
    i = 0
    while i < n:
        ch = pattern[i]
        if ch != '*':
            revealed[i] = ch
            guessed[ch] = 1
        i += 1

    candidates = []
    wi = 0
    while wi < m:
        w = words[wi]
        ok = 1
        i = 0
        while i < n:
            if i in revealed:
                if w[i] != revealed[i]:
                    ok = 0
                    break
            else:
                if w[i] in guessed:
                    ok = 0
                    break
            i += 1
        if ok:
            candidates.append(w)
        wi += 1

    possible = {}
    ci = 0
    while ci < len(candidates):
        w = candidates[ci]
        i = 0
        while i < n:
            if pattern[i] == '*':
                ch = w[i]
                if ch not in guessed:
                    possible[ch] = 1
            i += 1
        ci += 1

    ans = 0
    for ch in possible:
        good = 1
        ci = 0
        while ci < len(candidates):
            w = candidates[ci]
            found = 0
            i = 0
            while i < n:
                if pattern[i] == '*' and w[i] == ch:
                    found = 1
                    break
                i += 1
            if found == 0:
                good = 0
                break
            ci += 1
        if good:
            ans += 1
    return ans

